def is_majority(arr, n, x):
    # Find the first occurrence of x
    first_occurrence = first(arr, 0, n-1, x, n)

    # If x is not present in the array, return False
    if first_occurrence == -1:
        return False

    # Check if the element at position (first_occurrence + n/2) is x
    # If it is, then x is the majority element
    if (first_occurrence + n // 2) <= (n - 1) and arr[first_occurrence + n // 2] == x:
        return True
    else:
        return False

def first(arr, low, high, x, n):
    if high >= low:
        mid = low + (high - low) // 2
        # Checks if the element at mid is the first occurrence of x
        if (mid == 0 or x > arr[mid - 1]) and arr[mid] == x:
            return mid
        # If x is greater, ignore left half
        elif x > arr[mid]:
            return first(arr, (mid + 1), high, x, n)
        # If x is smaller, ignore right half
        else:
            return first(arr, low, (mid - 1), x, n)
    return -1

